-- Draft manufacturing and quality schema; depends on 001 and 002.
begin;
create table erp.boms(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, output_item_id uuid not null references erp.items);
create table erp.bom_versions(id uuid primary key default gen_random_uuid(), bom_id uuid not null references erp.boms, version integer not null check(version>0), output_quantity numeric(18,6) not null check(output_quantity>0), status text not null default 'draft' check(status in ('draft','approved','retired')), unique(bom_id,version));
create table erp.bom_components(id uuid primary key default gen_random_uuid(), version_id uuid not null references erp.bom_versions, item_id uuid not null references erp.items, quantity numeric(18,6) not null check(quantity>0), stage text not null check(stage in ('blend','roast','grind','flavor','pack')));
create table erp.work_orders(id uuid primary key default gen_random_uuid(), code text unique not null, version_id uuid references erp.bom_versions, planned_quantity numeric(18,6) not null check(planned_quantity>0), status text not null default 'draft' check(status in ('draft','approved','running','completed','cancelled')), created_at timestamptz not null default now());
create table erp.operations(id uuid primary key default gen_random_uuid(), work_order_id uuid references erp.work_orders, stage text not null check(stage in ('blend','roast','grind','flavor','pack')), sequence_no integer not null default 1 check(sequence_no>0), status text not null default 'draft' check(status in ('draft','running','completed','cancelled')), stock_document_id uuid unique references erp.stock_documents, started_at timestamptz, completed_at timestamptz, unique(work_order_id,sequence_no));
create table erp.operation_costs(id uuid primary key default gen_random_uuid(), operation_id uuid not null references erp.operations, category text not null check(category in ('labor','energy','depreciation','maintenance','rent','other')), amount numeric(24,8) not null check(amount>=0), notes text);
create table erp.quality_specs(id uuid primary key default gen_random_uuid(), item_id uuid references erp.items, stage text not null, test_name text not null, result_kind text not null check(result_kind in ('numeric','boolean','text')), min_value numeric, max_value numeric, unit text, active boolean not null default true, check(min_value is null or max_value is null or min_value<=max_value));
create table erp.inspections(id uuid primary key default gen_random_uuid(), lot_id uuid not null references erp.lots, operation_id uuid references erp.operations, status text not null default 'pending' check(status in ('pending','passed','failed')), inspected_by uuid references auth.users, inspected_at timestamptz);
create table erp.inspection_results(id uuid primary key default gen_random_uuid(), inspection_id uuid not null references erp.inspections, spec_id uuid not null references erp.quality_specs, spec_snapshot jsonb not null, numeric_result numeric, boolean_result boolean, text_result text, passed boolean not null, check(num_nonnulls(numeric_result,boolean_result,text_result)=1), unique(inspection_id,spec_id));
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='erp' loop execute format('alter table erp.%I enable row level security',t.tablename); end loop; end $$;
commit;
-- Required: approved BOM immutability, operation sequencing, QC release rules,
-- mass balance, cost allocation, stock posting and authorization.
